package org.xar.ck3.control.application.planning.military;

import static org.xar.ck3.control.application.planning.military.CombatEuJson.*;
import static org.xar.ck3.control.application.planning.military.CombatEntryEuContract.*;
import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.node.ArrayNode;
import com.fasterxml.jackson.databind.node.ObjectNode;
import java.math.BigInteger;
import java.util.ArrayList;
import java.util.List;
import org.xar.ck3.control.wave2.military.forecast.CombatCore;

/** Explicit trial tapes are the sole source of costs; no synthetic defaults or alternate combat model. */
final class CombatEntryEuActions {
    private CombatEntryEuActions() { }
    private static final List<String> ALTERNATIVES=List.of("avoid","wait_reinforce"),COUNTS=List.of("wins","losses","no_resolution");
    private record Trial(List<BigInteger> components){Trial{components=List.copyOf(components);}BigInteger get(String key){return components.get(COEFFICIENTS.indexOf(key));}}
    private static boolean validTrials(JsonNode rows,BigInteger count){if(rows==null||!rows.isArray()||!BigInteger.valueOf(rows.size()).equals(count))return false;for(JsonNode row:rows){if(!schema(row,COEFFICIENTS))return false;for(String key:COEFFICIENTS)if(!raw(row.get(key)))return false;}return true;}
    private static List<Trial> trials(JsonNode rows){List<Trial> out=new ArrayList<>();for(JsonNode row:rows){List<BigInteger> components=new ArrayList<>();for(String key:COEFFICIENTS)components.add(n(row.get(key)));out.add(new Trial(components));}return List.copyOf(out);}
    private static BigInteger sum(List<Trial> rows,String key){BigInteger result=BigInteger.ZERO;for(Trial row:rows)result=result.add(row.get(key));return result;}
    private static BigInteger utility(List<Trial> rows,JsonNode coefficients){BigInteger total=BigInteger.ZERO;for(Trial row:rows)for(String key:COEFFICIENTS)total=total.add(product(row.get(key),n(coefficients.get(key))));return total.divide(BigInteger.valueOf(rows.size()));}
    static ObjectNode assess(ObjectNode value,JsonNode action,ObjectNode base){ObjectNode result=base.deepCopy().put("action_components_version",ACTION_COMPONENTS_VERSION).put("action_components_contract_sha256",ACTION_COMPONENTS_CONTRACT_SHA256).put("action_components_ready",false).putNull("candidate_action");List<String> errors=new ArrayList<>();boolean ready=base.path("external_inputs_ready").booleanValue();if(!ready)errors.add("base_contract_not_ready");boolean shape=schema(action,words("version identity experiment_input_sha256 per_trial_component_vector_sha256 policy_sha256 attack_trial_components_raw alternatives"));if(!shape)errors.add("action_components_schema_invalid");else if(ready){
            if(!same(action.get("version"),J.textNode(ACTION_COMPONENTS_VERSION)))errors.add("action_components_version_mismatch");if(!same(action.get("identity"),value.get("identity")))errors.add("action_components_identity_mismatch");JsonNode experiment=value.get("experiment"),policy=value.get("utility_policy");if(!same(action.get("experiment_input_sha256"),experiment.get("input_sha256"))||!same(action.get("per_trial_component_vector_sha256"),experiment.get("per_trial_component_vector_sha256"))||!same(action.get("policy_sha256"),policy.get("policy_sha256")))errors.add("action_components_versioned_source_mismatch");BigInteger count=n(experiment.get("trial_count"));JsonNode attack=action.get("attack_trial_components_raw");if(!validTrials(attack,count))errors.add("attack_trial_components_invalid");else{if(!digest(attack).equals(experiment.path("per_trial_component_vector_sha256").asText()))errors.add("attack_trial_components_sha256_mismatch");List<Trial> rows=trials(attack);boolean oneHot=true;for(Trial row:rows){List<BigInteger> outcomes=List.of(row.get("player_win"),row.get("player_loss"),row.get("no_resolution")).stream().sorted().toList();if(!outcomes.equals(List.of(BigInteger.ZERO,BigInteger.ZERO,SCALE))){oneHot=false;errors.add("attack_trial_outcome_not_one_hot");break;}}if(oneHot)for(int i=0;i<COUNTS.size();i++){BigInteger observed=BigInteger.ZERO;for(Trial row:rows)if(row.components.get(i).equals(SCALE))observed=observed.add(BigInteger.ONE);if(!observed.equals(n(experiment.get(COUNTS.get(i))))){errors.add("attack_trial_outcome_count_mismatch");break;}}summaryErrors(value,rows,errors);}
            JsonNode alternatives=action.get("alternatives");if(!schema(alternatives,ALTERNATIVES))errors.add("alternative_actions_invalid");else for(String alternative:ALTERNATIVES){JsonNode projection=alternatives.get(alternative);if(!schema(projection,words("trial_components_raw uncertainty_penalty_raw opportunity_cost_raw"))){errors.add(alternative+"_projection_schema_invalid");continue;}if(!validTrials(projection.get("trial_components_raw"),count))errors.add(alternative+"_trial_components_invalid");for(String penalty:List.of("uncertainty_penalty_raw","opportunity_cost_raw"))if(!raw(projection.get(penalty))||n(projection.get(penalty)).signum()<0)errors.add(alternative+"_"+penalty+"_invalid");}
            for(String penalty:PENALTIES)if(n(policy.get(penalty)).signum()<0)errors.add("attack_"+penalty+"_negative");JsonNode distribution=value.get("distribution");for(int i=0;i<COUNTS.size();i++)if(n(distribution.get(DISTRIBUTION.get(i))).multiply(count).subtract(n(experiment.get(COUNTS.get(i))).multiply(SCALE)).abs().compareTo(count)>0)errors.add(DISTRIBUTION.get(i)+"_trial_count_mismatch");
            BigInteger wins=n(experiment.get("wins")),resolved=wins.add(n(experiment.get("losses")));CombatCore.WilsonInterval wilson=wilson(wins,resolved);JsonNode interval=distribution.get("resolved_win_wilson95");if(wilson==null||Math.abs(n(interval.get("low_raw")).doubleValue()-wilson.lower()*100000)>1.5||Math.abs(n(interval.get("high_raw")).doubleValue()-wilson.upper()*100000)>1.5)errors.add("resolved_win_wilson95_trial_count_mismatch");
        }
        result.set("action_components_errors",strings(errors));if(!errors.isEmpty()){result.put("status","blocked_incomplete_or_invalid");ArrayNode blockers=(ArrayNode)base.get("blockers").deepCopy();blockers.add("action_components_not_ready");result.set("blockers",blockers);seal(result);return result;}
        JsonNode policy=value.get("utility_policy"),distribution=value.get("distribution"),coefficients=policy.get("coefficients_raw"),alternatives=action.get("alternatives");BigInteger attack=utility(trials(action.get("attack_trial_components_raw")),coefficients).subtract(n(policy.get("uncertainty_penalty_raw"))).subtract(n(policy.get("opportunity_cost_raw")));List<BigInteger> alternativeEu=new ArrayList<>();for(String key:ALTERNATIVES){JsonNode projection=alternatives.get(key);alternativeEu.add(utility(trials(projection.get("trial_components_raw")),coefficients).subtract(n(projection.get("uncertainty_penalty_raw"))).subtract(n(projection.get("opportunity_cost_raw"))));}JsonNode risk=policy.get("risk_constraints");List<String> failures=new ArrayList<>();if(n(distribution.path("resolved_win_wilson95").get("low_raw")).compareTo(n(risk.get("min_resolved_win_wilson_low_raw")))<0)failures.add("resolved_win_wilson_low");if(n(distribution.get("player_stack_wipe_probability_raw")).compareTo(n(risk.get("max_player_stack_wipe_probability_raw")))>0)failures.add("player_stack_wipe");if(n(value.path("character_tails").get("player_one_life_catastrophic_probability_raw")).compareTo(n(risk.get("max_player_one_life_catastrophic_probability_raw")))>0)failures.add("player_one_life_catastrophic");int best=alternativeEu.get(1).compareTo(alternativeEu.get(0))>0?1:0;BigInteger margin=attack.subtract(alternativeEu.get(best));String candidate=failures.isEmpty()&&margin.compareTo(n(policy.get("minimum_attack_margin_raw")))>0?"attack":ALTERNATIVES.get(best);result.put("status",ACTIVATION_ENABLED?"selected":"calculated_not_activated").put("action_components_ready",true).put("action_components_sha256",digest(action)).put("eu_attack_raw",attack).put("eu_avoid_raw",alternativeEu.get(0)).put("eu_wait_reinforce_raw",alternativeEu.get(1)).put("attack_margin_raw",margin).put("candidate_action",candidate).put("decision_status",ACTIVATION_ENABLED?"selected":"candidate_only").put("automatic_attack_enabled",ACTIVATION_ENABLED&&candidate.equals("attack"));if(failures.isEmpty())result.putNull("dominant_risk");else result.put("dominant_risk",failures.get(0));if(ACTIVATION_ENABLED)result.put("selected_action",candidate);else result.putNull("selected_action");result.set("blockers",ACTIVATION_ENABLED?arr():strings(List.of("combat_entry_eu_activation_not_enabled")));seal(result);return result;
    }
    /** Use the selected shared kernel; the large-count adapter retains Python's exact integer-to-binary64 ratios. */
    private static CombatCore.WilsonInterval wilson(BigInteger successes,BigInteger count){if(count.signum()<=0)return null;if(count.bitLength()<32)return CombatCore.wilsonInterval95(successes.intValueExact(),count.intValueExact());double z=1.959963984540054,p=CombatCore.ratio(successes,count),z2=z*z,trials=count.doubleValue();require(Double.isFinite(trials),"trial count exceeds binary64 interval domain");double denominator=1.0+z2/trials;double center=(p+z2/(2.0*trials))/denominator;double half=z*Math.sqrt(p*(1.0-p)/trials+z2/(4.0*trials*trials))/denominator;return new CombatCore.WilsonInterval(Math.max(0.0,center-half),Math.min(1.0,center+half));}
    private static void summaryErrors(JsonNode value,List<Trial> rows,List<String> errors){int count=rows.size();String[] fields={"battle_day","player_hard_loss","enemy_hard_loss"},groups={"battle_days","player_hard_losses_raw","enemy_hard_losses_raw"};for(int i=0;i<fields.length;i++){String field=fields[i],group=groups[i];List<BigInteger> values=new ArrayList<>(rows.stream().map(r->r.get(field)).sorted().toList());if(values.stream().anyMatch(v->v.signum()<0)){errors.add("attack_trial_"+field+"_negative");continue;}if(i==0){BigInteger horizon=n(value.path("experiment").get("horizon_days")).multiply(SCALE);if(values.stream().anyMatch(v->v.remainder(SCALE).signum()!=0||v.compareTo(horizon)>0)){errors.add("attack_trial_battle_day_invalid");continue;}values=values.stream().map(v->v.divide(SCALE)).toList();}int[] numerators={1,5,9};for(int q=0;q<3;q++){int rank=(int)Math.max(1,((long)numerators[q]*count+9)/10);if(!n(value.path("distribution").path(group).get(QUANTILES.get(q))).equals(values.get(rank-1)))errors.add("attack_trial_"+group+"_"+QUANTILES.get(q)+"_mismatch");}}
        String[] tailFields={"player_commander_wound","player_commander_maim","player_commander_death","player_knight_death","player_detach_capture","player_one_life_catastrophic"},tailNames={"commander_wound_probability_raw","commander_maim_probability_raw","commander_death_probability_raw","knight_death_probability_raw","detach_or_capture_probability_raw","player_one_life_catastrophic_probability_raw"};BigInteger c=BigInteger.valueOf(count);for(int i=0;i<tailFields.length;i++){String field=tailFields[i];boolean indicator=rows.stream().allMatch(r->r.get(field).equals(BigInteger.ZERO)||r.get(field).equals(SCALE));JsonNode published=i==5?value.path("character_tails").get(tailNames[i]):value.path("character_tails").path("player").get(tailNames[i]);if(!indicator)errors.add("attack_trial_"+field+"_not_indicator");else if(sum(rows,field).subtract(n(published).multiply(c)).abs().compareTo(c)>0)errors.add("attack_trial_"+field+"_probability_mismatch");}for(String key:CAMPAIGN){String field=key.substring(0,key.length()-4);if(sum(rows,field).subtract(n(value.path("campaign_feedback").get(key)).multiply(c)).abs().compareTo(c)>0)errors.add("attack_trial_"+field+"_campaign_mismatch");}}
}
